package dev.zomboid.isotacz;
import java.util.*;
/** Selection uses visual outlines, rather than collision shapes or the player's gun sight. */
public final class CursorTarget {
 static Object[] ray(Object mc){Object window=R.call(mc,"getWindow"),mouse=R.get(mc,"mouseHandler"),renderer=R.get(mc,"gameRenderer"),camera=R.call(renderer,"getMainCamera"),pos=R.call(camera,"getPosition");double nx=2*R.num(R.call(mouse,"xpos"))/R.num(R.call(window,"getScreenWidth"))-1,ny=1-2*R.num(R.call(mouse,"ypos"))/R.num(R.call(window,"getScreenHeight"));double aspect=R.num(R.call(window,"getWidth"))/R.num(R.call(window,"getHeight")),fov=R.num(R.call(renderer,"callGetFov",camera,(float)R.num(R.call(camera,"getPartialTickTime")),true));Rules.Ray ray=Rules.cursor(Bridge.v(pos,"x"),Bridge.v(pos,"y"),Bridge.v(pos,"z"),R.num(R.call(camera,"getYRot")),R.num(R.call(camera,"getXRot")),nx,ny,aspect,fov,R.yes(R.get(Bridge.config(),"ortho")),R.num(R.call(Bridge.mod(),"getZoom")));double[] o=ray.origin(),d=ray.direction();Object start=Bridge.vec(o[0],o[1],o[2]),end=Bridge.vec(o[0]+128*d[0],o[1]+128*d[1],o[2]+128*d[2]);return new Object[]{start,end};}
 static Object pick(Object mc){Object[] ray=ray(mc);return pickRay(mc,ray[0],ray[1]);}
 static Object pickRay(Object mc,Object start,Object end){Object player=R.get(mc,"player"),level=R.get(mc,"level"),eye=R.call(player,"getEyePosition");double range=Math.min(8,R.num(R.call(player,"blockInteractionRange")));int radius=(int)Math.ceil(range)+1,cx=(int)Math.floor(Bridge.v(eye,"x")),cy=(int)Math.floor(Bridge.v(eye,"y")),cz=(int)Math.floor(Bridge.v(eye,"z"));Object bestHit=null;double best=Double.POSITIVE_INFINITY;
  for(int x=cx-radius;x<=cx+radius;x++)for(int y=cy-radius;y<=cy+radius;y++)for(int z=cz-radius;z<=cz+radius;z++){Object pos=R.make("net.minecraft.core.BlockPos",x,y,z);if(Bridge.blockDistance(eye,pos)>range)continue;Object state=R.call(level,"getBlockState",pos);if(R.yes(R.call(state,"isAir")))continue;boolean remains=Bridge.remains(Bridge.blockId(state));if(!remains&&!R.yes(R.call(R.type("com.cleannrooster.dungeons_iso.util.InteractionTargeting"),"isInteractable",level,pos)))continue;Object shape=R.call(state,"getShape",level,pos),box;
   if(R.yes(R.call(shape,"isEmpty"))){if(!remains)continue;box=R.make("net.minecraft.world.phys.AABB",(double)x-.1,(double)y,(double)z-.1,(double)x+1.1,(double)y+.35,(double)z+1.1);}else box=R.call(R.call(shape,"bounds"),"move",(double)x,(double)y,(double)z);
   Optional<?> point=(Optional<?>)R.call(box,"clip",start,end);if(point.isEmpty())continue;double d=Bridge.distance(start,point.get());if(d>=best)continue;Object hit=R.make("net.minecraft.world.phys.BlockHitResult",point.get(),R.get(R.type("net.minecraft.core.Direction"),"UP"),pos,false);if(Bridge.interactable(mc,hit)){best=d;bestHit=hit;}
  }
  Object box=R.call(R.type("net.minecraft.world.phys.AABB"),"ofSize",start,1d,1d,1d);box=R.call(R.call(box,"expandTowards",R.call(end,"subtract",start)),"inflate",.4d);java.util.function.Predicate<Object> filter=Bridge::corpse;
  for(Object entity:(List<?>)R.call(level,"getEntities",player,box,filter)){Object bounds=R.call(R.call(entity,"getBoundingBox"),"inflate",.25d);Optional<?> point=(Optional<?>)R.call(bounds,"clip",start,end);if(point.isEmpty())continue;double d=Bridge.distance(start,point.get());if(d>=best)continue;Object hit=R.make("net.minecraft.world.phys.EntityHitResult",entity,point.get());if(Bridge.interactable(mc,hit)){best=d;bestHit=hit;}}
  return bestHit;
 }
}
